  /* 狄利克雷 (1, 1, 1) 就是三角形上的均匀分布：用确定性随机数撒点（−log u 归一化） */
  function dirichletPts(n, seed) {
    var out = [];
    for (var i = 0; i < n; i++) {
      var a = -Math.log(1 - rnd(3 * i, seed)), b = -Math.log(1 - rnd(3 * i + 1, seed)), c = -Math.log(1 - rnd(3 * i + 2, seed)), s = a + b + c;
      out.push([a / s, b / s, c / s]);
    }
    return out;
  }

