  /* 课程的示意：一个环境的 α 怎么走。规则照代码（> 210 步加 0.02、< 200 步减 0.02），回合长短是编的：α 越大越容易早早摔倒 */
  function currTrace(n) {
    var a = CURR.init, out = [];
    for (var k = 0; k < n; k++) {
      var p = 0.92 - 1.1 * Math.max(0, a - 0.55), len = rnd(k, 5) < p ? 240 + 60 * rnd(k, 6) : 60 + 130 * rnd(k, 7);
      out.push({ a: a, len: len });
      if (len > CURR.up) a += CURR.step; else if (len < CURR.down) a -= CURR.step;
      a = clamp(a, 0, 1);
    }
    return out;
  }

